'use strict'

const { describe, it, before } = require('mocha')
const assert = require('node:assert')
const AsyncLocalStorage = require('node:async_hooks').AsyncLocalStorage
const { createHash } = require('node:crypto')
const { once } = require('node:events')
const http = require('node:http')
const zlib = require('node:zlib')
const onFinished = require('on-finished')
const request = require('supertest')

const bodyParser = require('..')
const json = require('body-parser/json')

const hasZstandardSupport = 'createZstdDecompress' in zlib
const zstandardit = hasZstandardSupport ? it : it.skip
const nozstandardit = !hasZstandardSupport ? it : it.skip

describe('bodyParser.json()', function () {
  it('should parse JSON', function (done) {
    request(createServer())
      .post('/')
      .set('Content-Type', 'application/json')
      .send('{"user":"tobi"}')
      .expect(200, '{"user":"tobi"}', done)
  })

  it('should handle Content-Length: 0', function (done) {
    request(createServer())
      .get('/')
      .set('Content-Type', 'application/json')
      .set('Content-Length', '0')
      .expect(200, '{}', done)
  })

  it('should handle empty message-body', function (done) {
    request(createServer())
      .get('/')
      .set('Content-Type', 'application/json')
      .set('Transfer-Encoding', 'chunked')
      .expect(200, '{}', done)
  })

  it('should handle no message-body', function (done) {
    request(createServer())
      .get('/')
      .set('Content-Type', 'application/json')
      .unset('Transfer-Encoding')
      .expect(200, 'undefined', done)
  })

  it('should 400 when only whitespace', function (done) {
    request(createServer())
      .post('/')
      .set('Content-Type', 'application/json')
      .send('  \n')
      .expect(400, '[entity.parse.failed] ' + parseError(' '), done)
  })

  it('should 400 when invalid content-length', function (done) {
    const jsonParser = bodyParser.json()
    const server = createServer(function (req, res, next) {
      req.headers['content-length'] = '20' // bad length
      jsonParser(req, res, next)
    })

    request(server)
      .post('/')
      .set('Content-Type', 'application/json')
      .send('{"str":')
      .expect(400, /content length/, done)
  })

  it('should handle consumed request', function (done) {
    const jsonParser = bodyParser.json()
    const server = createServer(function (req, res, next) {
      req.on('end', function () {
        jsonParser(req, res, next)
      })
      req.resume()
    })

    request(server)
      .post('/')
      .set('Content-Type', 'application/json')
      .send('{"user":"tobi"}')
      .expect(200, 'undefined', done)
  })

  it('should handle duplicated middleware', function (done) {
    const jsonParser = bodyParser.json()
    const server = createServer(function (req, res, next) {
      jsonParser(req, res, function (err) {
        if (err) return next(err)
        jsonParser(req, res, next)
      })
    })

    request(server)
      .post('/')
      .set('Content-Type', 'application/json')
      .send('{"user":"tobi"}')
      .expect(200, '{"user":"tobi"}', done)
  })

  describe('when JSON is invalid', function () {
    before(function () {
      this.server = createServer()
    })

    it('should 400 for bad token', function (done) {
      request(this.server)
        .post('/')
        .set('Content-Type', 'application/json')
        .send('{:')
        .expect(400, '[entity.parse.failed] ' + parseError('{:'), done)
    })

    it('should 400 for incomplete', function (done) {
      request(this.server)
        .post('/')
        .set('Content-Type', 'application/json')
        .send('{"user"')
        .expect(400, '[entity.parse.failed] ' + parseError('{"user"'), done)
    })

    it('should include original body on error object', function (done) {
      request(this.server)
        .post('/')
        .set('Content-Type', 'application/json')
        .set('X-Error-Property', 'body')
        .send(' {"user"')
        .expect(400, ' {"user"', done)
    })
  })

  describe('with limit option', function () {
    it('should 413 when over limit with Content-Length', function (done) {
      const buf = Buffer.alloc(1024, '.')
      request(createServer({ limit: '1kb' }))
        .post('/')
        .set('Content-Type', 'application/json')
        .set('Content-Length', '1034')
        .send(JSON.stringify({ str: buf.toString() }))
        .expect(413, '[entity.too.large] request entity too large', done)
    })

    it('should 413 when over limit with chunked encoding', function (done) {
      const buf = Buffer.alloc(1024, '.')
      const server = createServer({ limit: '1kb' })
      const test = request(server).post('/')
      test.set('Content-Type', 'application/json')
      test.set('Transfer-Encoding', 'chunked')
      test.write('{"str":')
      test.write('"' + buf.toString() + '"}')
      test.expect(413, done)
    })

    it('should 413 when inflated body over limit', function (done) {
      const server = createServer({ limit: '1kb' })
      const test = request(server).post('/')
      test.set('Content-Encoding', 'gzip')
      test.set('Content-Type', 'application/json')
      test.write(Buffer.from('1f8b080000000000000aab562a2e2952b252d21b05a360148c58a0540b0066f7ce1e0a040000', 'hex'))
      test.expect(413, done)
    })

    it('should accept number of bytes', function (done) {
      const buf = Buffer.alloc(1024, '.')
      request(createServer({ limit: 1024 }))
        .post('/')
        .set('Content-Type', 'application/json')
        .send(JSON.stringify({ str: buf.toString() }))
        .expect(413, done)
    })

    it('should not change when options altered', function (done) {
      const buf = Buffer.alloc(1024, '.')
      const options = { limit: '1kb' }
      const server = createServer(options)

      options.limit = '100kb'

      request(server)
        .post('/')
        .set('Content-Type', 'application/json')
        .send(JSON.stringify({ str: buf.toString() }))
        .expect(413, done)
    })

    it('should not hang response', function (done) {
      const buf = Buffer.alloc(10240, '.')
      const server = createServer({ limit: '8kb' })
      const test = request(server).post('/')
      test.set('Content-Type', 'application/json')
      test.write(buf)
      test.write(buf)
      test.write(buf)
      test.expect(413, done)
    })

    it('should not error when inflating', function (done) {
      const server = createServer({ limit: '1kb' })
      const test = request(server).post('/')
      test.set('Content-Encoding', 'gzip')
      test.set('Content-Type', 'application/json')
      test.write(Buffer.from('1f8b080000000000000aab562a2e2952b252d21b05a360148c58a0540b0066f7ce1e0a0400', 'hex'))
      test.expect(413, done)
    })
  })

  // @see https://github.com/expressjs/body-parser/security/advisories/GHSA-27r3-jxmh-p828
  // Uses a raw socket (not supertest) so the trailing bytes reach the decoder
  // after it has already finished the valid frame, which is what triggers the
  // crash. A valid frame alone decodes and responds; the trailing bytes then
  // error on the finished decoder and, without the fix, that error is uncaught.
  describe('with trailing bytes after a compressed body', function () {
    it('should finish the request when the decompressor finishes early', async function () {
      const jsonParser = json()
      const first = Buffer.concat([
        zlib.deflateSync(Buffer.from('{"a":1}')),
        Buffer.from([0x00])
      ])
      const trailing = Buffer.alloc(1024)
      let client

      const server = createServer(function (req, res, next) {
        jsonParser(req, res, function (err) {
          if (err) return next(err)
          // Downstream middleware waits for the entire HTTP request to finish.
          onFinished(req, next)
          client.end(trailing)
        })
      })

      try {
        server.listen(0, '127.0.0.1')
        await once(server, 'listening')

        const response = await new Promise(function (resolve, reject) {
          client = http.request({
            host: '127.0.0.1',
            port: server.address().port,
            method: 'POST',
            agent: false,
            headers: {
              'Content-Type': 'application/json',
              'Content-Encoding': 'deflate',
              'Content-Length': first.length + trailing.length
            }
          }, function (res) {
            let body = ''
            res.setEncoding('utf8')
            res.on('data', function (chunk) { body += chunk })
            res.on('error', reject)
            res.on('end', function () { resolve({ res, body }) })
          })
          client.on('error', reject)
          client.setTimeout(1000, function () {
            client.destroy(new Error('Timed out waiting for the HTTP request to finish'))
          })
          client.write(first)
        })

        assert.strictEqual(response.res.statusCode, 200)
        assert.strictEqual(response.body, '{"a":1}')
      } finally {
        if (client) client.destroy()
        await new Promise(function (resolve) { server.close(resolve) })
      }
    })

    it('should preserve other consumers of the request body', async function () {
      const jsonParser = json()
      const first = Buffer.concat([
        zlib.deflateSync(Buffer.from('{"a":1}')),
        Buffer.from([0x00])
      ])
      const trailing = Buffer.alloc(1024)
      const expectedHash = createHash('sha256').update(first).update(trailing).digest('hex')
      let client

      const server = createServer(function (req, res, next) {
        // A second middleware hashes the raw request for an audit log.
        const hash = createHash('sha256')
        req.pipe(hash)

        jsonParser(req, res, function (err) {
          if (err) return next(err)
          hash.once('finish', function () {
            res.setHeader('X-Body-SHA256', hash.digest('hex'))
            next()
          })
          // Ensure the last bytes arrive after the decompressor has finished.
          client.end(trailing)
        })
      })

      try {
        server.listen(0, '127.0.0.1')
        await once(server, 'listening')

        const response = await new Promise(function (resolve, reject) {
          client = http.request({
            host: '127.0.0.1',
            port: server.address().port,
            method: 'POST',
            agent: false,
            headers: {
              'Content-Type': 'application/json',
              'Content-Encoding': 'deflate',
              'Content-Length': first.length + trailing.length
            }
          }, function (res) {
            let body = ''
            res.setEncoding('utf8')
            res.on('data', function (chunk) { body += chunk })
            res.on('error', reject)
            res.on('end', function () { resolve({ res, body }) })
          })
          client.on('error', reject)
          client.setTimeout(1000, function () {
            client.destroy(new Error('Timed out waiting for the request body hash'))
          })
          client.write(first)
        })

        assert.strictEqual(response.res.statusCode, 200)
        assert.strictEqual(response.body, '{"a":1}')
        assert.strictEqual(response.res.headers['x-body-sha256'], expectedHash)
      } finally {
        if (client) client.destroy()
        await new Promise(function (resolve) { server.close(resolve) })
      }
    })

    it('should not crash on trailing bytes after a gzip body', function (done) {
      const server = createServer()
      server.listen(0, '127.0.0.1', function () {
        const port = server.address().port
        const body = Buffer.concat([
          zlib.gzipSync(Buffer.from('{"a":1}')),
          Buffer.from([0x00]),
          Buffer.alloc(100 * 1024, 0x58)
        ])
        const req = http.request({
          host: '127.0.0.1',
          port,
          method: 'POST',
          path: '/',
          headers: {
            'Content-Type': 'application/json',
            'Content-Encoding': 'gzip',
            'Content-Length': body.length
          }
        }, function (res) {
          let data = ''
          res.on('data', function (c) { data += c })
          res.on('end', function () {
            // let the trailing bytes reach the finished decoder before asserting
            setTimeout(function () {
              server.close()
              assert.strictEqual(res.statusCode, 200)
              assert.strictEqual(data, '{"a":1}')
              done()
            }, 200)
          })
        })
        req.on('error', done)
        req.end(body)
      })
    })

    it('should not crash when an unsupported charset rejects a compressed body', function (done) {
      const server = createServer({ verify: function () {} })
      server.listen(0, '127.0.0.1', function () {
        const port = server.address().port
        const body = Buffer.concat([
          zlib.gzipSync(Buffer.from('{"a":1}')),
          Buffer.from([0x00]),
          Buffer.alloc(100 * 1024, 0x58)
        ])
        const req = http.request({
          host: '127.0.0.1',
          port,
          method: 'POST',
          path: '/',
          headers: {
            'Content-Type': 'application/json; charset=utf-999',
            'Content-Encoding': 'gzip',
            'Content-Length': body.length
          }
        }, function (res) {
          res.on('data', function () {})
          res.on('end', function () {
            setTimeout(function () {
              server.close()
              assert.strictEqual(res.statusCode, 415)
              done()
            }, 200)
          })
        })
        req.on('error', done)
        req.end(body)
      })
    })
  })

  describe('with inflate option', function () {
    describe('when false', function () {
      before(function () {
        this.server = createServer({ inflate: false })
      })

      it('should not accept content-encoding', function (done) {
        const test = request(this.server).post('/')
        test.set('Content-Encoding', 'gzip')
        test.set('Content-Type', 'application/json')
        test.write(Buffer.from('1f8b080000000000000bab56ca4bcc4d55b2527ab16e97522d00515be1cc0e000000', 'hex'))
        test.expect(415, '[encoding.unsupported] content encoding unsupported', done)
      })
    })

    describe('when true', function () {
      before(function () {
        this.server = createServer({ inflate: true })
      })

      it('should accept content-encoding', function (done) {
        const test = request(this.server).post('/')
        test.set('Content-Encoding', 'gzip')
        test.set('Content-Type', 'application/json')
        test.write(Buffer.from('1f8b080000000000000bab56ca4bcc4d55b2527ab16e97522d00515be1cc0e000000', 'hex'))
        test.expect(200, '{"name":"论"}', done)
      })
    })
  })

  describe('with strict option', function () {
    describe('when undefined', function () {
      before(function () {
        this.server = createServer()
      })

      it('should 400 on primitives', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('true')
          .expect(400, '[entity.parse.failed] ' + parseError('#rue').replace(/#/g, 't'), done)
      })
    })

    describe('when false', function () {
      before(function () {
        this.server = createServer({ strict: false })
      })

      it('should parse primitives', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('true')
          .expect(200, 'true', done)
      })
    })

    describe('when true', function () {
      before(function () {
        this.server = createServer({ strict: true })
      })

      it('should not parse primitives', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('true')
          .expect(400, '[entity.parse.failed] ' + parseError('#rue').replace(/#/g, 't'), done)
      })

      it('should not parse primitives with leading whitespaces', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('    true')
          .expect(400, '[entity.parse.failed] ' + parseError('    #rue').replace(/#/g, 't'), done)
      })

      it('should allow leading whitespaces in JSON', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('   { "user": "tobi" }')
          .expect(200, '{"user":"tobi"}', done)
      })

      it('should handle all RFC 7159 whitespace characters before JSON', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('\x20\x09\x0a\x0d{ "user": "tobi" }')
          .expect(200, '{"user":"tobi"}', done)
      })

      it('should error on body with only RFC 7159 whitespace characters', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('\x20\x09\x0a\x0d')
          .expect(400, '[entity.parse.failed] ' + parseError('\x20\x09\x0a\x0d'), done)
      })

      it('should include correct message in stack trace', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .set('X-Error-Property', 'stack')
          .send('true')
          .expect(400)
          .expect(shouldContainInBody(parseError('#rue').replace(/#/g, 't')))
          .end(done)
      })
    })
  })

  describe('with type option', function () {
    describe('when "application/vnd.api+json"', function () {
      before(function () {
        this.server = createServer({ type: 'application/vnd.api+json' })
      })

      it('should parse JSON for custom type', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/vnd.api+json')
          .send('{"user":"tobi"}')
          .expect(200, '{"user":"tobi"}', done)
      })

      it('should ignore standard type', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('{"user":"tobi"}')
          .expect(200, 'undefined', done)
      })
    })

    describe('when ["application/json", "application/vnd.api+json"]', function () {
      before(function () {
        this.server = createServer({
          type: ['application/json', 'application/vnd.api+json']
        })
      })

      it('should parse JSON for "application/json"', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/json')
          .send('{"user":"tobi"}')
          .expect(200, '{"user":"tobi"}', done)
      })

      it('should parse JSON for "application/vnd.api+json"', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/vnd.api+json')
          .send('{"user":"tobi"}')
          .expect(200, '{"user":"tobi"}', done)
      })

      it('should ignore "application/x-json"', function (done) {
        request(this.server)
          .post('/')
          .set('Content-Type', 'application/x-json')
          .send('{"user":"tobi"}')
          .expect(200, 'undefined', done)
      })
    })

    describe('when a function', function () {
      it('should parse when truthy value returned', function (done) {
        const server = createServer({ type: accept })

        function accept (req) {
          return req.headers['content-type'] === 'application/vnd.api+json'
        }

        request(server)
          .post('/')
          .set('Content-Type', 'application/vnd.api+json')
          .send('{"user":"tobi"}')
          .expect(200, '{"user":"tobi"}', done)
      })

      it('should work without content-type', function (done) {
        const server = createServer({ type: accept })

        function accept (req) {
          return true
        }

        const test = request(server).post('/')
        test.write('{"user":"tobi"}')
        test.expect(200, '{"user":"tobi"}', done)
      })

      it('should not invoke without a body', function (done) {
        const server = createServer({ type: accept })

        function accept (req) {
          throw new Error('oops!')
        }

        request(server)
          .get('/')
          .expect(200, done)
      })
    })
  })

  describe('with verify option', function () {
    it('should assert value if function', function () {
      assert.throws(createServer.bind(null, { verify: 'lol' }),
        /TypeError: option verify must be function/)
    })

    it('should error from verify', function (done) {
      const server = createServer({
        verify: function (req, res, buf) {
          if (buf[0] === 0x5b) throw new Error('no arrays')
        }
      })

      request(server)
        .post('/')
        .set('Content-Type', 'application/json')
        .send('["tobi"]')
        .expect(403, '[entity.verify.failed] no arrays', done)
    })

    it('should allow custom codes', function (done) {
      const server = createServer({
        verify: function (req, res, buf) {
          if (buf[0] !== 0x5b) return
          const err = new Error('no arrays')
          err.status = 400
          throw err
        }
      })

      request(server)
        .post('/')
        .set('Content-Type', 'application/json')
        .send('["tobi"]')
        .expect(400, '[entity.verify.failed] no arrays', done)
    })

    it('should allow custom type', function (done) {
      const server = createServer({
        verify: function (req, res, buf) {
          if (buf[0] !== 0x5b) return
          const err = new Error('no arrays')
          err.type = 'foo.bar'
          throw err
        }
      })

      request(server)
        .post('/')
        .set('Content-Type', 'application/json')
        .send('["tobi"]')
        .expect(403, '[foo.bar] no arrays', done)
    })

    it('should include original body on error object', function (done) {
      const server = createServer({
        verify: function (req, res, buf) {
          if (buf[0] === 0x5b) throw new Error('no arrays')
        }
      })

      request(server)
        .post('/')
        .set('Content-Type', 'application/json')
        .set('X-Error-Property', 'body')
        .send('["tobi"]')
        .expect(403, '["tobi"]', done)
    })

    it('should allow pass-through', function (done) {
      const server = createServer({
        verify: function (req, res, buf) {
          if (buf[0] === 0x5b) throw new Error('no arrays')
        }
      })

      request(server)
        .post('/')
        .set('Content-Type', 'application/json')
        .send('{"user":"tobi"}')
        .expect(200, '{"user":"tobi"}', done)
    })

    it('should work with different charsets', function (done) {
      const server = createServer({
        verify: function (req, res, buf) {
          if (buf[0] === 0x5b) throw new Error('no arrays')
        }
      })

      const test = request(server).post('/')
      test.set('Content-Type', 'application/json; charset=utf-16')
      test.write(Buffer.from('feff007b0022006e0061006d00650022003a00228bba0022007d', 'hex'))
      test.expect(200, '{"name":"论"}', done)
    })

    it('should 415 on unknown charset prior to verify', function (done) {
      const server = createServer({
        verify: function (req, res, buf) {
          throw new Error('unexpected verify call')
        }
      })

      const test = request(server).post('/')
      test.set('Content-Type', 'application/json; charset=x-bogus')
      test.write(Buffer.from('00000000', 'hex'))
      test.expect(415, '[charset.unsupported] unsupported charset "X-BOGUS"', done)
    })
  })

  describe('async local storage', function () {
    before(function () {
      const jsonParser = bodyParser.json()
      const store = { foo: 'bar' }

      this.server = createServer(function (req, res, next) {
        const asyncLocalStorage = new AsyncLocalStorage()

        asyncLocalStorage.run(store, function () {
          jsonParser(req, res, function (err) {
            const local = asyncLocalStorage.getStore()

            if (local) {
              res.setHeader('x-store-foo', String(local.foo))
            }

            next(err)
          })
        })
      })
    })

    it('should persist store', function (done) {
      request(this.server)
        .post('/')
        .set('Content-Type', 'application/json')
        .send('{"user":"tobi"}')
        .expect(200)
        .expect('x-store-foo', 'bar')
        .expect('{"user":"tobi"}')
        .end(done)
    })

    it('should persist store when unmatched content-type', function (done) {
      request(this.server)
        .post('/')
        .set('Content-Type', 'application/fizzbuzz')
        .send('buzz')
        .expect(200)
        .expect('x-store-foo', 'bar')
        .expect('undefined')
        .end(done)
    })

    it('should persist store when inflated', function (done) {
      const test = request(this.server).post('/')
      test.set('Content-Encoding', 'gzip')
      test.set('Content-Type', 'application/json')
      test.write(Buffer.from('1f8b080000000000000bab56ca4bcc4d55b2527ab16e97522d00515be1cc0e000000', 'hex'))
      test.expect(200)
      test.expect('x-store-foo', 'bar')
